from flask import Flask, request, jsonify
import datetime

app = Flask(__name__)

@app.route('/taxe_to_celsius')
def taxe_to_celsius():
    input = request.args.get('taxe')
    return str((float(input.split()[0]) - 32) * 5/9)

if __name__ == '__main__':
    app.run()

