import pickle

def save_data(data):
    with open('data.pkl','wb') as f:
        pickle.dump(data, f)

def load_data():
    with open('data.pkl','rb') as f:
        data = pickle.load(f)
    return data

if __name__ == '__main__':
    data = {
        'title': 'Behind Every Great Man...',
        'description': "The stay-at-home wife's secret during an affair"
    }
    save_data(data)

    loaded = load_data()
    print('Description:', loaded['description'])

